import sys
def jump(nums):
    res = far = end = 0
    for i in range(len(nums)-1):
        far = max(far, i + nums[i])
        if i == end: res += 1; end = far
    return res
if __name__ == '__main__':
    line = sys.stdin.read().strip()
    if line: print(jump(eval(line.replace(' ', ','))))
